from typing import List

class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        K = 401
        req = {}
        for e, c in requirements:
            req[e] = c
        dp = [0] * K
        dp[0] = 1
        for i in range(n):
            # prefix sums of dp
            pre = [0] * (K + 1)
            for k in range(K):
                pre[k + 1] = (pre[k] + dp[k]) % MOD
            new = [0] * K
            for k in range(K):
                # sum dp[k-c] for c in [0, i], i.e. indices from max(0,k-i) to k
                lo = k - i
                if lo < 0:
                    lo = 0
                new[k] = (pre[k + 1] - pre[lo]) % MOD
            dp = new
            if i in req:
                c = req[i]
                val = dp[c] if c < K else 0
                dp = [0] * K
                dp[c] = val
        return sum(dp) % MOD
